51	            "description": "Git SHAs included in this changeset"
52	          }
53	        }
54	      }
55	    },
56	    "breaking_changes": {
57	      "type": "array",
58	      "items": { "type": "string" },
59	      "description": "Human-readable descriptions of all breaking changes in this release"
60	    },
61	    "migration_guide": {
62	      "type": "string",
63	      "description": "Optional: instructions for upgrading from the previous version"
64	    },
65	    "reasoning": {
66	      "type": "string",
67	      "description": "Agent scratchpad — not consumed downstream"
68	    }
69	  }
70	}
