17	        "schema_id": { "type": "string", "enum": ["plan@1", "spec@1"] },
18	        "sha256": { "type": "string", "pattern": "^sha256:[0-9a-f]{64}$" }
19	      }
20	    },
21	    "task": {
22	      "type": "object",
23	      "required": ["id", "title", "files", "steps", "commit_message"],
