33	            "modify": { "type": "array", "items": { "type": "string" } },
34	            "test": { "type": "array", "items": { "type": "string" } }
35	          }
36	        },
37	        "steps": { "type": "array", "items": { "type": "string" } },
38	        "commit_message": { "type": "string" },
39	        "depends_on": { "type": "array", "items": { "type": "string" }, "uniqueItems": true },
40	        "covers_criteria": { "type": "array", "items": { "type": "string" }, "uniqueItems": true }
41	      }
42	    },
43	    "criterion": {
