50	        "is_error_case": { "type": "boolean" },
51	        "judgment_call": { "type": "boolean" },
52	        "rationale": { "type": "string" }
53	      }
54	    },
55	    "gap": {
56	      "type": "object",
57	      "required": ["kind", "finding"],
58	      "additionalProperties": false,
59	      "properties": {
60	        "kind": {
61	          "enum": ["missing_modify_target", "missing_test_target", "dependency_completion_unverified"]
62	        },
