64	        "task_id": { "type": "string", "minLength": 1 },
65	        "path": { "type": "string", "minLength": 1 }
66	      }
67	    },
68	    "success": {
69	      "type": "object",
70	      "required": [
71	        "contract_id",
72	        "status",
73	        "selection",
74	        "sources",
75	        "plan_context",
76	        "spec_context",
77	        "tasks",
78	        "criteria",
79	        "checks",
80	        "gaps",
81	        "evidence_scope",
82	        "output_limit_bytes"
83	      ],
84	      "additionalProperties": false,
85	      "properties": {
86	        "contract_id": { "const": "implementation-context@1" },
87	        "status": { "const": "ok" },
88	        "selection": {
89	          "type": "object",
90	          "required": ["mode", "id", "task_ids", "criterion_ids"],
91	          "additionalProperties": false,
92	          "properties": {
93	            "mode": { "enum": ["batch", "task"] },
