106	          }
107	        },
108	        "plan_context": {
109	          "type": "object",
110	          "required": ["goal", "architecture"],
111	          "additionalProperties": false,
112	          "properties": {
113	            "goal": { "type": "string" },
114	            "architecture": { "type": "string" }
115	          }
116	        },
