118	          "type": "object",
119	          "required": ["id", "purpose", "scope", "non_goals"],
120	          "additionalProperties": false,
121	          "properties": {
122	            "id": { "type": "string", "minLength": 1 },
123	            "purpose": { "type": "string" },
124	            "scope": { "type": "string" },
