129	                "type": "object",
130	                "required": ["name", "signature", "description"],
131	                "additionalProperties": false,
132	                "properties": {
133	                  "name": { "type": "string" },
134	                  "signature": { "type": "string" },
135	                  "description": { "type": "string" },
136	                  "error_conditions": { "type": "array", "items": { "type": "string" } }
137	                }
138	              }
139	            }
140	          }
141	        },
142	        "tasks": { "type": "array", "minItems": 1, "items": { "$ref": "#/$defs/task" } },
143	        "criteria": { "type": "array", "items": { "$ref": "#/$defs/criterion" } },
144	        "checks": {
145	          "type": "array",
146	          "minItems": 6,
147	          "maxItems": 6,
148	          "uniqueItems": true,
149	          "items": {
150	            "type": "object",
151	            "required": ["id", "result"],
152	            "additionalProperties": false,
153	            "properties": {
154	              "id": {
155	                "enum": ["plan_schema", "spec_schema", "source_links", "spec_hash", "selection", "input_stability"]
156	              },
157	              "result": { "const": "passed" }
158	            }
159	          }
160	        },
161	        "gaps": { "type": "array", "items": { "$ref": "#/$defs/gap" } },
162	        "evidence_scope": { "const": "artifacts_only" },
163	        "output_limit_bytes": { "type": "integer", "minimum": 256, "maximum": 1048576 }
164	      }
165	    },
166	    "failure": {
167	      "type": "object",
168	      "required": ["contract_id", "status", "error"],
169	      "additionalProperties": false,
170	      "properties": {
171	        "contract_id": { "const": "implementation-context@1" },
172	        "status": { "const": "error" },
173	        "error": {
174	          "type": "object",
175	          "required": ["code", "check", "message"],
176	          "additionalProperties": false,
177	          "properties": {
178	            "code": {
179	              "enum": [
180	                "invalid_input",
181	                "unsafe_path",
182	                "missing_source",
183	                "invalid_json",
184	                "schema_violation",
185	                "link_mismatch",
186	                "spec_drift",
187	                "invalid_selection",
188	                "inputs_changed",
189	                "budget_exceeded",
190	                "filesystem_error"
191	              ]
192	            },
193	            "check": { "type": "string", "minLength": 1 },
194	            "path": { "type": "string", "minLength": 1 },
195	            "message": { "type": "string", "maxLength": 160 }
196	          }
197	        }
198	      }
199	    }
200	  }
201	}
